# 【算法思路】用环形覆写数组封装经验回放池，并基于在线网络 Q 值与目标网络最大未来值计算均方 TD 误差。
import numpy as np

# 固定容量环形覆盖写入与随机小批量抽样
class ReplayBuffer:
    def __init__(self, cap):
        self.buf = []
        self.cap = cap
        self.pos = 0

    def push(self, s, a, r, s2, d):
        if len(self.buf) < self.cap:
            self.buf.append((s, a, r, s2, d))
        else:
            self.buf[self.pos] = (s, a, r, s2, d)
        self.pos = (self.pos + 1) % self.cap

    def sample(self, n):
        idx = np.random.choice(len(self.buf), n)
        return [self.buf[i] for i in idx]

# 依据终止标记区分单步目标值计算批次均方 TD 损失
def compute_td_loss(batch, online, target, gamma=0.9):
    online, target = np.asarray(online, dtype=float), np.asarray(target, dtype=float)
    loss = 0.0
    for s, a, r, s2, d in batch:
        q_target = r if d else r + gamma * float(np.max(target[s2]))
        loss += (float(online[s][a]) - q_target) ** 2
    return float(loss / len(batch))

# 验证环形覆写位置与存储元素长度
def eval_replay_buffer(capacity: int, pushes: list) -> dict:
    rb = ReplayBuffer(capacity)
    for s, a, r, s2, d in pushes:
        rb.push(s, a, r, s2, d)
    return {"size": len(rb.buf), "pos": rb.pos, "buf": [list(item) for item in rb.buf]}

# 【算法思路】反向递推计算广义优势估计 (GAE) 平衡偏差方差，并构造 PPO 近端策略截断替代目标。
import numpy as np
# 从后往前按 gamma 与 lambda 累积时序差分优势值
def compute_advantages(rewards, values, gamma=0.99, lam=0.95):
    advantages = []
    gae = 0
    for t in reversed(range(len(rewards))):
        delta = rewards[t] + gamma * (values[t+1] if t+1<len(values) else 0) - values[t]
        gae = delta + gamma * lam * gae
        advantages.insert(0, gae)
    return np.array(advantages, dtype=float)
# 比较未裁剪与截断后策略重要性比值乘积目标
def ppo_clip_surrogate(old_logp, new_logp, adv, eps=0.2):
    ratio = np.exp(new_logp - old_logp)
    clipped = np.clip(ratio, 1-eps, 1+eps)
    return -min(ratio * adv, clipped * adv)

