# 【算法思路】生成带下界保底的指数衰减探索率曲线并实现 epsilon-贪心动作选择器。
import random

# 随机探索或按当前状态价值表挑出最高分动作
def epsilon_greedy(Q, state, epsilon):
    values = Q[state]
    if random.random() < epsilon:
        return random.randrange(len(values))
    return max(range(len(values)), key=values.__getitem__)

# 按指数比率衰减但始终不低于下界 eps_end
def decay_schedule(eps_start, eps_end, decay, steps):
    return [max(eps_end, eps_start * decay ** step) for step in range(steps)]

# 【算法思路】在同策 SARSA 框架下引入累加资格迹 (Eligibility Traces) 把末端延迟奖赏回传给既往状态动作对。
import random

# 每步计算 TD 误差并按累加资格迹同时回溯更新全状态空间 Q 表
def sarsa_lambda(env, episodes, alpha, gamma, epsilon, lam):
    transitions = env["transitions"]
    q = [[0.0] * len(actions) for actions in transitions]

    def choose(state):
        actions = q[state]
        if random.random() < epsilon:
            return random.randrange(len(actions))
        return max(range(len(actions)), key=actions.__getitem__)

    for _ in range(episodes):
        traces = [[0.0] * len(actions) for actions in transitions]
        state = env["start"]
        if not q[state]:
            continue
        action = choose(state)
        while True:
            next_state, reward, done = transitions[state][action]
            next_action = None if done else choose(next_state)
            next_value = 0.0 if done else q[next_state][next_action]
            delta = reward + gamma * next_value - q[state][action]
            traces[state][action] += 1.0
            for s, actions in enumerate(q):
                for a in range(len(actions)):
                    actions[a] += alpha * delta * traces[s][a]
                    traces[s][a] *= gamma * lam
            if done:
                break
            state, action = next_state, next_action
    return q
